import{_ as o,o as i,c as t,a2 as a}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0012 — Dettagli implementativi di console admin ed export (M5)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0012-admin-export-details.md","filePath":"adr/0012-admin-export-details.md"}'),n={name:"adr/0012-admin-export-details.md"};function c(d,e,l,r,s,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0012-—-dettagli-implementativi-di-console-admin-ed-export-m5" tabindex="-1">ADR-0012 — Dettagli implementativi di console admin ed export (M5) <a class="header-anchor" href="#adr-0012-—-dettagli-implementativi-di-console-admin-ed-export-m5" aria-label="Permalink to &quot;ADR-0012 — Dettagli implementativi di console admin ed export (M5)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.6.3, §2.6.5, §2.8.1, §2.8.2, §3.1, §3.2.2, §3.5.2, §3.5.5, §3.6 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-24</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.6.2–2.6.4 (quota, export), §3.5.5 (admin), §3.6 (<code>AccountChanged</code>), §3.8 (cifratura), D-03, D-05</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, in modo additivo (migrazione 0005, codici d&#39;errore su operazioni admin, <code>S3_PUBLIC_ENDPOINT</code>, <code>quota_bytes</code> opzionale)</td></tr></tbody></table><p><strong>Aggiornamento 2026-11-02.</strong> Il ruolo in <code>users.role</code> come semplice specchio del token è superato da ADR-0041 (<code>role_changed_at</code>: il cambio dalla console prevale sui token emessi prima); l&#39;indirizzo IP è ora registrato in <code>audit_log</code>.</p><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>M5 aggiunge le API di amministrazione (utenti allineati a Keycloak, gruppi, profili, limiti, audit), l&#39;export ZIP e le relative UI. Lo spec fissa i confini ma lascia aperti alcuni dettagli.</p><h2 id="decisioni" tabindex="-1">Decisioni <a class="header-anchor" href="#decisioni" aria-label="Permalink to &quot;Decisioni&quot;">​</a></h2><ol><li><strong>Migrazione <code>0005_admin.sql</code></strong> (la roadmap la chiamava <code>0004_admin</code>, già occupata da gruppi e condivisioni): <code>config_profile_versions</code> (con riempimento dei profili esistenti), <code>export_jobs</code>, <code>storage_snapshots</code> (trend del cruscotto) e indici su <code>audit_log(actor_id|action, at)</code>.</li><li><strong>Ruolo admin</strong>: ogni handler <code>/admin/*</code> richiede <code>principal.IsAdmin()</code> (<code>403 FORBIDDEN</code> altrimenti). Il ruolo in <code>users.role</code> è lo specchio del claim del token, riletto a ogni login; un cambio di ruolo avviene quindi in Keycloak (ruolo realm <code>memobrain-admin</code>) <strong>e</strong> nello specchio. Non si può sospendere o eliminare se stessi, né togliersi il ruolo, né rimuovere l&#39;ultimo amministratore attivo (<code>409 INVALID_STATE</code>).</li><li><strong>Client Keycloak con privilegi minimi</strong> (<code>internal/keycloak</code>): service account con <code>manage-users</code>, <code>view-users</code>, <code>query-users</code> (niente <code>view-realm</code>). Il ruolo <code>memobrain-admin</code> si risolve da <code>role-mappings/realm[/available]</code> dell&#39;utente, non da <code>GET /roles/{name}</code>: lo ha scoperto il test contro il Keycloak reale (<code>KC_LIVE_URL=http://localhost:8080 go test ./internal/keycloak -run Live</code>), che i fake non avrebbero rivelato. Un utente creato senza password temporanea riceve <code>UPDATE_PASSWORD</code> e <code>VERIFY_EMAIL</code>. Senza <code>KC_ADMIN_*</code> il client è <code>Disabled</code>: le operazioni che lo richiedono rispondono <code>409 INVALID_STATE</code>, quelle su utenti solo-DB (installazioni standalone) proseguono.</li><li><strong>Sospensione</strong>: lo stato nel DB è la barriera effettiva (la cache di stato del middleware dura 30 s; sulla replica che serve l&#39;operazione viene invalidata subito); poi Keycloak disabilita l&#39;account e revoca le sessioni. Se Keycloak fallisce l&#39;utente è comunque bloccato e il ritentativo completa l&#39;operazione. Evento <code>AccountChanged</code> (<code>suspended</code>, <code>activated</code>, <code>quota_changed</code>) sul canale NOTIFY <code>account_changed</code>: lo stream gRPC si chiude con <code>PERMISSION_DENIED</code> dopo <code>suspended</code>; SSE emette <code>account_changed</code>. L&#39;eliminazione porta l&#39;utente a <code>deleted</code>, manda i suoi vault in retention e disabilita (non cancella) l&#39;account Keycloak: lo username non è riutilizzabile.</li><li><strong>Quota</strong>: <code>quota_bytes</code> assente o <code>null</code> = default globale, <code>-1</code> = illimitata (campo opzionale nello schema OpenAPI, perché il generatore non distingue <code>null</code>). Le modifiche (singole e in blocco, max 500 utenti) emettono <code>AccountChanged</code>.</li><li><strong>Profili di configurazione</strong>: ogni creazione o modifica (anche la retrocessione del profilo globale uscente) scrive uno snapshot in <code>config_profile_versions</code>. Il ripristino è una nuova versione col contenuto di quella vecchia; <code>is_global</code> resta quello attuale del profilo.</li><li><strong>Cruscotto storage</strong>: contatori e top consumer calcolati sui dati vivi con la quota di default; il trend legge <code>storage_snapshots</code>, scritto dal job notturno di manutenzione (e alla lettura del cruscotto, così non resta vuoto nel primo giorno). Soglie e limiti sono le chiavi <code>settings</code> già seminate, validate (<code>1 ≤ warn &lt; critical ≤ 100</code>, retention giornaliera ≥ retention).</li><li><strong>Audit</strong>: ordine per <code>id</code> decrescente con cursore a chiave (<code>next_cursor</code>), filtri attore/azione (prefisso)/target/intervallo; CSV fino a 50 000 righe con neutralizzazione delle formule (celle che iniziano con <code>= + - @</code>). L&#39;indirizzo IP non è ancora registrato (<code>audit.Record</code> non lo riceve): colonna presente, vuota.</li><li><strong>Export (cloud)</strong>: solo il proprietario, vault condiviso, mai privato (<code>VAULT_ENCRYPTED</code>: il server ha solo cifrato). <code>GET /vaults/{vid}/export.zip</code> in streaming fino a 512 MB (<code>409 INVALID_STATE</code> oltre: serve un job); <code>POST …/exports</code> crea un job che un worker (<code>jobs</code>, ogni 15 s) costruisce in un file temporaneo e carica nel bucket <code>S3_BUCKET_EXPORTS</code> come <code>exports/&lt;id&gt;.zip</code> (nei test e in dev senza S3 usa lo store dei blob). Il link vale 24 h, poi il job passa a <code>expired</code> e l&#39;archivio è cancellato; un job <code>running</code> da più di un&#39;ora è rimesso in coda. <code>download_url</code> è un URL presigned solo se è configurato <code>S3_PUBLIC_ENDPOINT</code> (l&#39;endpoint interno di solito non è raggiungibile dal browser); altrimenti è il percorso autenticato <code>…/exports/{id}/download</code>. I file escono con <code>deflate</code> per i formati testuali e <code>store</code> per il resto; sono esclusi i percorsi che <code>pathrules.IsExcluded</code> dichiara device-specific (la sync li rifiuta già). Ogni export è registrato in audit (<code>vault.export</code>).</li><li><strong>Export (desktop)</strong>: comando &quot;Esporta vault come ZIP&quot; → <code>VaultAPI.ExportZip</code> con il dialogo nativo &quot;Salva con nome&quot;; scrive in un file <code>.part</code> accanto alla destinazione e lo rinomina a fine corsa; rifiuta una destinazione dentro il vault; esclude i dati device-specific e il cestino <code>.trash/</code>; include le cartelle vuote.</li><li><strong>Web UI</strong>: console admin sotto <code>/admin/*</code> (storage, limiti, utenti, gruppi, profili, audit); la validazione client dei profili controlla solo le chiavi di primo livello e i <code>locked_keys</code> dallo schema (gli errori completi arrivano dal server). Lo ZIP è scritto da un writer proprio in <code>packages/vaultcrypto-web</code> (STORE, CRC-32, nomi UTF-8, data descriptor, ZIP64 a livello di archivio; una singola voce oltre 4 GiB fallisce con <code>ZipLimitError</code>), verificato con un lettore indipendente e con <code>python zipfile</code>/<code>unzip -t</code>. Vault privato: sblocco (passphrase o recovery key) e salvataggio sono due passi, perché <code>showSaveFilePicker</code> richiede un gesto utente recente; per ogni file si verifica lo SHA-256 del cifrato, i percorsi non sicuri o duplicati e i blob corrotti sono saltati e riportati. Un <code>download_url</code> presigned di altra origine si apre per navigazione (la CSP <code>connect-src</code> non ammette fetch cross-origin).</li><li><strong>CSP</strong>: <code>script-src</code> ammette <code>&#39;wasm-unsafe-eval&#39;</code>, necessario ad Argon2id (WebAssembly); <code>unsafe-inline</code> e <code>unsafe-eval</code> restano vietati.</li></ol><h2 id="limiti-noti" tabindex="-1">Limiti noti <a class="header-anchor" href="#limiti-noti" aria-label="Permalink to &quot;Limiti noti&quot;">​</a></h2><ul><li><p>Il percorso <code>showSaveFilePicker</code> non è coperto da test automatici (solo il fallback Blob); il bundle web pesa circa 600 KB per il wasm di Argon2.</p></li><li><p>La lista sessioni mostra le sessioni SSO di Keycloak, non i token del desktop.</p></li><li><p>Senza SMTP in Keycloak il reset password richiede il cambio al prossimo accesso ma non invia l&#39;e-mail (<code>email_sent=false</code>).</p></li><li><p>L&#39;export server non include le cartelle vuote (il server non le conosce).</p></li><li><p>Il trend ha un punto per giorno di manutenzione (o di apertura del cruscotto).</p></li></ul>',9)])])}const g=o(n,[["render",c]]);export{m as __pageData,g as default};
